contract InvMutTest is Test {
    C c;
    address bank;
    uint initialBankBalance;
    uint totalTickets;
    uint totalFeesPaid;

    function setUp() public {
        c = new C();
        bank = c.bank();
        initialBankBalance = bank.balance;
        totalTickets = 0;
        totalFeesPaid = 0;
    }

    function testFuzz_property(uint8 n) public {
        vm.assume(n > 0 && n <= 20);
        address player = address(uint160(uint(keccak256(abi.encodePacked(n)))));
        vm.deal(player, 10 ether);

        for (uint i = 0; i < n; i++) {
            vm.prank(player);
            try c.play{value: 10}() {
                totalTickets += 10;
                if (c.pot() == 0) {
                    totalFeesPaid += 1;
                }
            } catch {
                // ignore reverts, they don't change state
            }
        }

        assertTrue(bank.balance - initialBankBalance + c.pot() == totalTickets - totalFeesPaid);
    }
}

