pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 winSeed) public {
        // The bug only manifests when random == 0 (win).
        // We need to control randomness indirectly. Since block.timestamp and block.difficulty
        // are controllable in Foundry, we can set them to make random == 0.
        // However, the fuzzer provides a seed, and we warp/roll to make the hash even.
        // Keep the domain wide: just warp and roll to a fuzzed timestamp and difficulty.
        uint256 timestamp = bound(winSeed, 1, type(uint64).max);
        uint256 difficulty = bound(uint256(keccak256(abi.encode(winSeed))), 1, type(uint256).max);
        vm.warp(timestamp);
        vm.roll(block.number + 1);
        vm.difficulty(difficulty);

        // We need to call play() as a player. Use a fuzzed address from the test environment.
        address player = address(uint160(uint256(keccak256(abi.encode(winSeed, "player")))));
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();

        // If random was 0, pot was transferred and reset. If random was 1, pot remains.
        // We cannot assert on the random outcome itself, but we can assert:
        // Either pot == 0 (win) or pot == 10 (loss).
        // The mutant breaks this when win occurs: pot becomes 1.
        uint256 potAfter = c.pot();
        assertTrue(potAfter == 0 || potAfter == 10);
    }
}

