import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playCount) public {
        // Bound playCount to a reasonable range to avoid OutOfGas.
        playCount = bound(playCount, 0, 50);
        // We need the bank address to forward fees; the bank is the deployer (this contract).
        // Fund this contract to pay for tickets.
        vm.deal(address(this), playCount * (10 ether) + 1 ether);

        // Simulate a series of plays, each time ensuring we send exactly 10 wei (not ether).
        // The contract uses literal 10, not 10 ether, so we must send 10 wei.
        // We need enough 10-wei tickets; vm.deal with sufficient wei.
        // However, the original OutOfGas happened due to huge inputs; bounding fixes it.
        for (uint256 i = 0; i < playCount; i++) {
            vm.prank(address(this));
            c.play{value: 10}();
        }

        // After the loop, if the pot is not zero, it must have been the result of
        // a non-winning play (random != 0) accumulating tickets.
        // In the reference, after a win, pot is reset to 0.
        // In the mutant, after a win, pot becomes 1.
        // So the mutant can end up with pot == 1 even after a win,
        // while the reference never has pot == 1 after a sequence of plays
        // (unless a single non-winning play with exactly 1 wei occurs, but tickets are 10 wei, so pot increments by 10).
        // Thus, assert that pot is not 1.
        // However, to be safe: the reference also never has pot == 1 at any moment
        // because the only addition is 10, and wins reset to 0.
        // In the mutant, after a win it becomes 1.
        // So the invariant "pot != 1" holds for the reference for all inputs.
        assertTrue(c.pot() != 1);
    }
}

