contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 amount, uint64 warp, uint64 roll) public {
        // bound amount to TICKET_AMOUNT exactly (the only admissible value)
        vm.assume(amount == 10);
        vm.deal(address(this), amount);

        // fuzz warp and roll to vary the randomness
        vm.warp(warp);
        vm.roll(roll);

        // call play()
        c.play{value: amount}();

        // After a call to play(), if pot is non-zero, it implies the random result was 1 (no win).
        // If pot is zero, the win did occur and pot was reset to 0.
        // The bug fails to reset pot to 0 on a win, so after a win scenario, pot will still show some value.
        // Since we cannot easily read the random result, we reason about the relationship:
        // The pot before the call must have been 0 (fresh contract).
        // After the call, if msg.value=10, pot should either be 10 (no win) or 0 (win + reset).
        // The bug leaves pot with stale value (not 0 and not 10) after a win payouts.
        // Specifically, after a win payout, correct C has pot == 0, buggy M has pot != 0.
        // Since pot will be 10 if no win, we check: (pot == 0) || (pot == 10).
        uint256 currentPot = c.pot();
        assertTrue(currentPot == 0 || currentPot == 10);
    }
}

