import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 numPlaysBefore, uint64 roll, uint64 fuzzSender) public {
        // numPlaysBefore >= 1 to ensure there is some non-winning play that builds pot
        vm.assume(numPlaysBefore >= 1);
        vm.assume(roll < 100);  // keep block.difficulty influence reasonably wide

        // Set up block context to influence randomness
        vm.roll(roll);
        vm.warp(fuzzSender);

        // Generate distinct senders for each play to avoid nonce/tx ordering issues
        address[5] memory senders;
        senders[0] = address(uint160(fuzzSender));
        for(uint i = 1; i < 5; i++) {
            senders[i] = address(uint160(uint256(keccak256(abi.encode(fuzzSender, i)))));
        }

        // Perform numPlaysBefore plays from different senders
        uint senderIdx = 0;
        for (uint i = 0; i < numPlaysBefore && i < 5; i++) {
            address player = senders[senderIdx++];
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
